        qmTraceLanguageVerification: "Persistencia del idioma verificada mediante ACCESS-I18N-005 en Chrome, Firefox y Edge.",
        qmTraceSearchTitle: "Buscador global del portfolio",
        qmTraceSearchRequirement: "Búsqueda global",
        qmTraceSearchStory: "Búsqueda",
        qmTraceSearchBDD: "Búsqueda global",
        qmTraceSearchStatus: "Implementado y verificado",
        qmTraceSearchVerification: "Buscador global implementado y verificado mediante pruebas funcionales y de regresión automatizadas con Selenium. Permite realizar búsquedas por términos exactos, parciales y relacionados, consultar resultados de las distintas páginas del portfolio y navegar directamente a las secciones correspondientes. La suite de búsqueda global registra 43/43 pruebas aprobadas en Chrome, 43/43 en Firefox y 43/43 en Edge, con un total de 129/129 ejecuciones aprobadas.",

        qmDefectsTitle: "05. Gestión de defectos",
        qmDefectsDescription: "La gestión de defectos comprende la identificación, documentación, comunicación, verificación y cierre de los problemas detectados durante las pruebas. Este procedimiento permite mantener evidencias, facilitar la colaboración del equipo y comprobar que las correcciones cumplen los resultados esperados.",
        qmDefectProcessEyebrow: "PROCEDIMIENTO DE QA",
        qmDefectProcessTitle: "Del hallazgo a la verificación",
        qmDefectProcessDescription: "Durante el desarrollo del portfolio, inicié el seguimiento de defectos mediante registros estructurados en Excel y posteriormente incorporé Jira para organizar su documentación, clasificación y seguimiento. Este proceso permite aplicar buenas prácticas de QA en entornos de trabajo colaborativos y equipos Scrum.",
        qmDefectStepsAria: "Etapas de gestión de defectos",
        qmDefectStep01Short: "Detectar",
        qmDefectStep01Subtitle: "Hallazgo y evidencia",
        qmDefectStep02Short: "Registrar",
        qmDefectStep02Subtitle: "Reporte documental",
        qmDefectStep03Short: "Comunicar",
        qmDefectStep03Subtitle: "Reproducción y corrección",
        qmDefectStep04Short: "Reprobar",
        qmDefectStep04Subtitle: "Validación de la solución",
        qmDefectStep05Short: "Cerrar",
        qmDefectStep05Subtitle: "Cierre documental",
        qmDefectActivitiesTitle: "Información y actividades clave",
        qmDefectPrevious: "← Anterior",
        qmDefectNext: "Siguiente →",
        qmDefectRetestTitle: "Control antes del cierre",
        qmDefectRetestDescription: "Si el defecto continúa reproduciéndose durante la reprueba, no debe cerrarse. Se actualiza su seguimiento y vuelve al circuito de análisis y corrección. El cierre se realiza únicamente después de verificar satisfactoriamente el comportamiento esperado.",
        qmDefectEvidenceEyebrow: "EVIDENCIA DEL PROYECTO",
        qmDefectEvidenceTitle: "Defectos documentados",
        qmDefectEvidenceDescription: "Los siguientes defectos fueron identificados durante las pruebas del portfolio y cuentan con registros de seguimiento. Seleccioná un identificador para consultar el problema, su clasificación y las verificaciones relacionadas.",
        qmBugSelectorAria: "Seleccionar defecto documentado",
        qmBugRequirementLabel: "Requisito relacionado",
        qmBugTestLabel: "Caso de prueba",
        qmBugSeverityLabel: "Severidad",
        qmBugPriorityLabel: "Prioridad",
        qmBugResolutionTitle: "Resolución y verificación",
        qmDefectDocumentationDescription: "Los reportes completos, los casos de prueba y las evidencias disponibles se encuentran en la sección de QA del portfolio.",
        qmDefectDocumentationLink: "Consultar regresión y defectos →",
        qmDefectFinalNote: "Los cinco defectos figuran como cerrados en los registros del proyecto. Las clasificaciones, los casos de prueba relacionados y las evidencias de verificación se presentan según la documentación disponible para cada incidencia, sin atribuir ejecuciones adicionales no registradas.",
        qmDefectStep01Title: "Detección y evidencia",
        qmDefectStep01Label: "Identificación del defecto",
        qmDefectStep01Description: "Durante la ejecución de las pruebas, se identifica un comportamiento que no coincide con el resultado esperado. Se registran los datos de prueba, el entorno y las evidencias disponibles, como capturas de pantalla o grabaciones, para demostrar el problema y facilitar su reproducción.",
        qmDefectStep01Activity01: "Identificar la funcionalidad afectada.",
        qmDefectStep01Activity02: "Comparar el resultado esperado con el obtenido.",
        qmDefectStep01Activity03: "Capturar pantallas o grabaciones del comportamiento.",
        qmDefectStep01Activity04: "Registrar el entorno y los datos utilizados.",
        qmDefectStep02Title: "Registro documental",
        qmDefectStep02Label: "Excel y Jira",
        qmDefectStep02Description: "Una vez identificado el defecto, se crea un registro documental. En el proyecto, el seguimiento comenzó mediante planillas Excel y posteriormente se incorporó Jira para organizar la información, clasificación y seguimiento de los defectos.",
        qmDefectStep02Activity01: "Asignar un identificador y un resumen claro.",
        qmDefectStep02Activity02: "Documentar descripción y pasos de reproducción.",
        qmDefectStep02Activity03: "Registrar severidad, prioridad y estado.",
        qmDefectStep02Activity04: "Relacionar requisitos, casos de prueba y evidencias.",
        qmDefectStep03Title: "Comunicación y corrección",
        qmDefectStep03Label: "Trabajo colaborativo",
        qmDefectStep03Description: "Además de registrar el defecto, es necesario comunicarlo al equipo para que pueda visualizarse y reproducirse. El responsable técnico analiza el problema, implementa la corrección y comunica cuándo está disponible para una nueva verificación. En Jira puede mantenerse el seguimiento del responsable y del estado de la incidencia.",
        qmDefectStep03Activity01: "Comunicar el defecto y su impacto.",
        qmDefectStep03Activity02: "Facilitar los pasos y datos de reproducción.",
        qmDefectStep03Activity03: "Dar seguimiento al responsable y la corrección.",
        qmDefectStep03Activity04: "Confirmar que existe una versión para reprueba.",
        qmDefectStep04Title: "Reprueba y validación",
        qmDefectStep04Label: "Control de calidad",
        qmDefectStep04Description: "Después de aplicar la corrección, QA vuelve a ejecutar el escenario que permitió detectar el defecto. Se compara la respuesta obtenida con el resultado esperado y, cuando corresponde, se realizan pruebas de regresión para comprobar que otras funcionalidades continúan funcionando.",
        qmDefectStep04Activity01: "Reejecutar el caso de prueba afectado.",
        qmDefectStep04Activity02: "Comparar el resultado obtenido con el esperado.",
        qmDefectStep04Activity03: "Conservar evidencia posterior a la corrección.",
        qmDefectStep04Activity04: "Verificar funcionalidades relacionadas.",
        qmDefectStep05Title: "Cierre documental",
        qmDefectStep05Label: "Defecto verificado",
        qmDefectStep05Description: "Cuando la corrección supera satisfactoriamente la reprueba, el defecto puede marcarse como cerrado. Se conserva su historial, las evidencias y las referencias a las pruebas realizadas. Si el problema persiste, vuelve al circuito de análisis y corrección en lugar de cerrarse.",
        qmDefectStep05Activity01: "Confirmar que el resultado esperado se cumple.",
        qmDefectStep05Activity02: "Actualizar el estado final del defecto.",
        qmDefectStep05Activity03: "Registrar la resolución y las evidencias disponibles.",
        qmDefectStep05Activity04: "Conservar el historial para futuras regresiones.",
        qmDefectStepCodePrefix: "ETAPA",
