        heroEyebrow: "QA TESTER · AI CONSULTANT · BUSINESS VISION",
        heroTitle1: "Real-world experience.",
        heroTitle2: "Technology.",
        heroTitle3: "Quality.",
        heroDescription: "My business experience and strategic perspective allow me to approach technology with a focus on its objectives: reducing risks, optimizing resources, and creating value. I combine software testing, API validation, and artificial intelligence to evaluate solutions and improve processes, with an emphasis on quality and business results.",
        heroAreasTitle: "PROFESSIONAL AREAS",
        heroQaTitle: "QA TESTER AUTOMATION",
