        cvTechPeriod: "2025 — PRESENT",
        cvTechTitle: "Technology development and practical projects",
        cvTechSubtitle: "QA Automation and Applied Artificial Intelligence",

        cvTechIntro: "Continuous development of knowledge through training, personal projects and hands-on technical labs, integrating software quality, automation and artificial intelligence. This stage complements my professional experience and represents my progression toward a technology specialization focused on solving real-world problems.",

        cvTechQaTitle: "QA Automation and Software Quality",
        cvTechQaDescription1: "Design and execution of functional, exploratory and regression tests for web applications. Development of automated tests using Selenium WebDriver and Java, exploration of BDD practices with Cucumber and Gherkin, and REST API validation using Postman, including HTTP responses, status codes and JSON structures.",
        cvTechQaDescription2: "Test case documentation, defect tracking, and analysis of user experience and interfaces. Exploration of Python for data validation and AI tools to support test design and maintenance.",

        cvTechAiTitle: "Artificial Intelligence and Process Automation",
        cvTechAiDescription1: "Exploration of automated workflows, REST API integration and artificial intelligence agents to optimize operational tasks. Development of Python scripts for data processing, integration with language models and automation of repetitive activities.",
        cvTechAiDescription2: "Interest in data analysis and metrics for decision-making, as well as applying AI to process validation, solution development and the improvement of QA tasks.",

        cvTechProjectLabel: "Featured project:",
        cvTechProjectDescription: "development of this portfolio as a practical integration project, applying web design, JavaScript, backend development with Node.js and Express, SQLite data persistence, API validation and automated testing.",

        cvSenzaRole: "Sales Consulting and Branch Operations",
        cvSenzaDescription1: "Provided personalized advice on furniture and home solutions, connecting each customer's needs with functional and commercial proposals. Participated in branch operations, inventory control, cash closing procedures and supplier coordination.",
        cvSenzaDescription2: "Also contributed to training new team members, sharing knowledge of products, customer service and daily operations. This experience strengthened my ability to understand customer needs, maintain effective processes and focus on service quality.",

        cvSelemaRole: "Sales Management, Sales and Operations",
        cvSelemaDescription1: "Developed consultative sales of furniture and home products, tailoring proposals to each customer's space, preferences and budget. Participated in store layout and product presentation to improve the shopping experience.",
        cvSelemaDescription2: "Managed cash closing procedures, bank deposits, order and payment tracking, supplier payments, and the receipt and handling of merchandise. Also took responsibility for branch sales organization and supported the training and development of sales staff. The role combined customer service, administration, operational coordination and everyday problem-solving.",

        cvDivinoRole: "Sales, Visual Merchandising and Team Coordination",
        cvDivinoDescription1: "Provided sales advice on clothing and accessories, identifying preferences and helping each customer find products suited to their style and needs. Participated in store organization, window display design, merchandise presentation, product receiving, and cash register control and closing.",
        cvDivinoDescription2: "Also took on responsibilities for branch coordination and team support. This experience strengthened my communication, organization, issue resolution and attention-to-detail skills.",

        cvPrestaCashRole: "Collections Management and Account Follow-up",
        cvPrestaCashDescription1: "Managed preventive and early-stage collections, contacted customers, coordinated payments with participating merchants and followed up on payment agreements. Participated in refinancing alternatives and updated information in the corresponding systems.",
        cvPrestaCashDescription2: "This experience reinforced the importance of data accuracy, systematic follow-up, clear communication and adherence to procedures when resolving specific situations.",

        cvAccRole: "Customer Service, Support and Sales Operations",
        cvAccDescription1: "Participated in customer service and support operations, customer retention, inbound sales, early-stage collections, and the management of complaints and requests. Also worked on upselling and cross-selling initiatives, market research and automated outbound communication campaigns, including IVR systems and voice recognition.",
        cvAccClientsIntro: "I worked on projects involving",
        cvAccClientsAnd: "and",
        cvAccDescription3: "This experience gave me firsthand knowledge of customer service processes, user needs, incident management and the operation of technology-supported services. It established a foundation that now connects my business experience with software quality analysis and automation.",

