        qmDefectStep01Title: "Detection and evidence",
        qmDefectStep01Label: "Defect identification",
        qmDefectStep01Description: "During test execution, behavior that does not match the expected result is identified. Test data, the environment, and available evidence, such as screenshots or recordings, are documented to demonstrate the issue and facilitate its reproduction.",
        qmDefectStep01Activity01: "Identify the affected functionality.",
        qmDefectStep01Activity02: "Compare the expected result with the actual result.",
        qmDefectStep01Activity03: "Capture screenshots or recordings of the behavior.",
        qmDefectStep01Activity04: "Record the environment and test data used.",
        qmDefectStep02Title: "Defect documentation",
        qmDefectStep02Label: "Excel and Jira",
        qmDefectStep02Description: "Once the defect has been identified, a documented record is created. In this project, tracking initially began with Excel spreadsheets, and Jira was subsequently introduced to organize defect information, classification, and tracking.",
        qmDefectStep02Activity01: "Assign an identifier and a clear summary.",
        qmDefectStep02Activity02: "Document the description and reproduction steps.",
        qmDefectStep02Activity03: "Record severity, priority, and status.",
        qmDefectStep02Activity04: "Link requirements, test cases, and evidence.",
        qmDefectStep03Title: "Communication and correction",
        qmDefectStep03Label: "Collaborative work",
        qmDefectStep03Description: "In addition to documenting the defect, it must be communicated to the team so that it can be reviewed and reproduced. The technical owner analyzes the issue, implements the correction, and communicates when it is available for retesting. Jira can be used to track the assigned owner and the issue status.",
        qmDefectStep03Activity01: "Communicate the defect and its impact.",
        qmDefectStep03Activity02: "Provide reproduction steps and test data.",
        qmDefectStep03Activity03: "Track the assigned owner and the correction.",
