        qmDefectStep04Title: "Retesting and validation",
        qmDefectStep04Label: "Quality assurance",
        qmDefectStep04Description: "After the correction has been applied, QA reruns the scenario that originally revealed the defect. The actual result is compared with the expected result, and regression testing is performed when appropriate to verify that other functionalities continue to work correctly.",
        qmDefectStep04Activity01: "Rerun the affected test case.",
        qmDefectStep04Activity02: "Compare the actual result with the expected result.",
        qmDefectStep04Activity03: "Preserve evidence collected after the correction.",
        qmDefectStep04Activity04: "Verify related functionalities.",
