        heroEyebrow: "QA TESTER · AI CONSULTANT · VISÃO DE NEGÓCIOS",
        heroTitle1: "Experiência real.",
        heroTitle2: "Tecnologia.",
        heroTitle3: "Qualidade.",
        heroDescription: "Minha experiência em negócios e minha visão estratégica me permitem abordar a tecnologia a partir de seus objetivos: reduzir riscos, otimizar recursos e gerar valor. Integro testes de software, validação de APIs e inteligência artificial para avaliar soluções e melhorar processos, com foco na qualidade e nos resultados do negócio.",
        heroAreasTitle: "ÁREAS PROFISSIONAIS",
        heroQaTitle: "QA TESTER AUTOMATION",
        heroQaDescription: "Qualidade de software, planejamento e execução de testes, validação de APIs e identificação de defeitos.",
        heroAiTitle: "AI CONSULTANT",
        heroAiDescription: "Aplicação de IA, automação de tarefas e exploração de soluções para melhorar processos.",

        aboutEyebrow: "SOBRE MIM",
        aboutTitle: "Tecnologia com critério. Qualidade com visão de negócios.",
        aboutParagraph1: "Minha trajetória profissional me permitiu compreender as necessidades das pessoas, os processos de trabalho e os objetivos comerciais. Essa experiência hoje serve de base para abordar a tecnologia com uma perspectiva prática: entender qual problema precisa ser resolvido, como avaliar uma solução e que valor ela pode oferecer.",
        aboutParagraph2: "Em QA Testing, concentro-me em avaliar a qualidade do software por meio de testes, validação de APIs, identificação de defeitos e automação. Em Inteligência Artificial, exploro como integrar APIs, interfaces, agentes e automações para atender a necessidades concretas e otimizar processos.",
        aboutParagraph3: "São duas perspectivas complementares: desenvolver soluções tecnológicas com inteligência e avaliar seu comportamento com critério, considerando tanto as necessidades dos usuários quanto os objetivos do negócio.",
        aboutCardEyebrow: "TRAJETÓRIA PROFISSIONAL",
        aboutCardTitle: "Uma trajetória voltada para a tecnologia",
        aboutCardDescription: "Do atendimento ao cliente, vendas e gestão comercial ao meu desenvolvimento atual em qualidade de software e inteligência artificial.",
        aboutCardButton: "Explorar minha experiência ↗",

        specialtiesEyebrow: "ESPECIALIDADES",
        specialtiesTitle: "Qualidade de software e inteligência artificial.",
        specialtiesDescription: "Convido você a explorar duas áreas complementares do meu desenvolvimento profissional: Quality Assurance e Inteligência Artificial. Por meio deste portfólio, você poderá conhecer como aplico ferramentas, metodologias e conhecimentos técnicos para desenvolver, avaliar e melhorar soluções tecnológicas, sempre considerando as necessidades dos usuários e os objetivos do negócio.",

        specialtiesQaHeading: "Explore Quality Assurance",
        specialtiesQaParagraph1: "Convido você a clicar nos cartões de Quality Assurance, onde poderá explorar quatro dimensões de um projeto tecnológico real. Em Frontend, descobrirá como uma interface é construída e validada, incluindo formulários, internacionalização, design responsivo e experiência do usuário. Em Backend, poderá interagir com APIs, executar testes e observar validações, respostas HTTP e persistência de dados.",
        specialtiesQaParagraph2: "Em QA, encontrará casos de teste documentados, automação com Selenium, testes de regressão, defeitos identificados e evidências dos resultados obtidos. Por fim, em Gestão da Qualidade, poderá conhecer como são organizados os requisitos, as histórias de usuário, os critérios de aceitação, os sprints e o acompanhamento das atividades de qualidade.",

        specialtiesAiHeading: "Descubra as possibilidades da Inteligência Artificial",
        specialtiesAiParagraph1: "Mais adiante, encontrará quatro áreas de desenvolvimento que fazem parte da minha abordagem em Inteligência Artificial: IA Generativa, voltada à análise de informações e à criação de conteúdo; Automação Inteligente, para conectar ferramentas e otimizar processos; Vibe Coding, que permite construir, revisar e aperfeiçoar aplicações com assistência de IA; e AI Apps, focada na integração de modelos e APIs em soluções digitais com funcionalidades concretas.",
        specialtiesAiParagraph2: "Essas áreas representam oportunidades de aplicação e evolução tecnológica que continuarei desenvolvendo e incorporando ao portfólio.",

        specialtiesClosing: "Duas especialidades, um mesmo propósito: compreender os desafios, aplicar tecnologia com critério e demonstrar resultados que gerem valor real.",

