        cvTechPeriod: "2025 — ATUALIDADE",
        cvTechTitle: "Desenvolvimento tecnológico e projetos práticos",
        cvTechSubtitle: "Automação de QA e Inteligência Artificial aplicada",

        cvTechIntro: "Desenvolvimento contínuo de conhecimentos por meio de formação, projetos próprios e laboratórios técnico-práticos, integrando qualidade de software, automação e inteligência artificial. Esta etapa complementa minha experiência profissional e representa minha evolução rumo a uma especialização tecnológica voltada à resolução de problemas reais.",

        cvTechQaTitle: "Automação de QA e qualidade de software",
        cvTechQaDescription1: "Planejamento e execução de testes funcionais, exploratórios e de regressão para aplicações web. Desenvolvimento de testes automatizados com Selenium WebDriver e Java, exploração de práticas BDD com Cucumber e Gherkin e validação de APIs REST por meio do Postman, incluindo respostas HTTP, códigos de status e estruturas JSON.",
        cvTechQaDescription2: "Documentação de casos de teste, acompanhamento de defeitos e análise da experiência do usuário e das interfaces. Exploração de Python para validação de dados e de ferramentas de IA como apoio ao planejamento e à manutenção dos testes.",

        cvTechAiTitle: "Inteligência artificial e automação de processos",
        cvTechAiDescription1: "Exploração de fluxos de trabalho automatizados, integração de APIs REST e agentes de inteligência artificial para otimizar tarefas operacionais. Desenvolvimento de scripts em Python para processamento de dados, integração com modelos de linguagem e automação de atividades repetitivas.",
        cvTechAiDescription2: "Interesse em análise de dados e métricas para a tomada de decisões, bem como na aplicação de IA à validação de processos, ao desenvolvimento de soluções e à melhoria das atividades de QA.",

        cvTechProjectLabel: "Projeto em destaque:",
        cvTechProjectDescription: "desenvolvimento deste portfólio como projeto prático de integração, aplicando design web, JavaScript, desenvolvimento backend com Node.js e Express, persistência de dados com SQLite, validação de APIs e testes automatizados.",

        cvSenzaRole: "Consultoria comercial e gestão de filial",
        cvSenzaDescription1: "Atendimento personalizado em móveis e soluções para o lar, conectando as necessidades de cada cliente a propostas funcionais e comerciais. Participação na organização da filial, controle de estoque, fechamento de caixa e coordenação com fornecedores.",
        cvSenzaDescription2: "Também colaborei na formação de novos integrantes da equipe, compartilhando conhecimentos sobre produtos, atendimento comercial e dinâmica de trabalho. Essa experiência fortaleceu minha capacidade de compreender necessidades, cuidar dos processos e manter o foco na qualidade do atendimento.",

        cvSelemaRole: "Gestão comercial, vendas e operações",
        cvSelemaDescription1: "Desenvolvimento de vendas consultivas de móveis e produtos para o lar, com propostas adaptadas ao espaço, às preferências e ao orçamento de cada cliente. Participação na ambientação da loja e na apresentação dos produtos para melhorar a experiência de compra.",
        cvSelemaDescription2: "Gestão de fechamento de caixa, depósitos, acompanhamento de pedidos e pagamentos, pagamentos a fornecedores e recebimento e movimentação de mercadorias. Também assumi atividades de organização comercial da filial e apoio e treinamento de vendedores. A função integrou atendimento ao cliente, administração, coordenação operacional e resolução de problemas cotidianos.",

        cvDivinoRole: "Vendas, visual merchandising e coordenação de equipe",
        cvDivinoDescription1: "Atendimento comercial em vestuário e acessórios, identificando preferências e ajudando cada cliente a encontrar produtos adequados ao seu estilo e às suas necessidades. Participação na organização da loja, montagem de vitrines, apresentação de mercadorias, recebimento de produtos e controle e fechamento de caixa.",
        cvDivinoDescription2: "Também assumi responsabilidades de coordenação da filial e apoio à equipe de trabalho. Essa etapa consolidou habilidades de comunicação, organização, resolução de ocorrências e atenção aos detalhes.",

        cvPrestaCashRole: "Gestão de cobranças e acompanhamento de contas",
        cvPrestaCashDescription1: "Gestão de cobranças preventivas e iniciais, contato com clientes, coordenação de pagamentos com estabelecimentos conveniados e acompanhamento de acordos. Participação em alternativas de refinanciamento e atualização de informações nos sistemas correspondentes.",
        cvPrestaCashDescription2: "Essa experiência reforçou a importância da precisão dos dados, do acompanhamento sistemático, da comunicação clara e do cumprimento de procedimentos para resolver situações concretas.",

        cvAccRole: "Atendimento ao cliente, suporte e gestão comercial",
