        qmTraceNavigationVerification: "A navegação do portfólio está vinculada a RF-07, HU-002 e BDD-003. TC-006 e TC-007 verificam links internos para seções do perfil. TC-019 verifica a navegação entre páginas e TC-020 os controles de retorno por meio do logotipo e dos botões. Os testes automatizados TC-019 e TC-020 foram concluídos com 12/12 PASS no Chrome, Firefox e Microsoft Edge, incluindo a verificação da visibilidade das seções de destino.",

        qmTraceContactTitle: "Formulário de contato",
