        qmTraceContactVerification: "A validação de mensagem vazia está documentada por meio de um teste de API que verifica a resposta HTTP 400. O envio de mensagens depende da configuração do serviço SMTP.",
        qmTraceLanguageTitle: "Seleção e persistência do idioma",
