        qmTraceSearchTitle: "Busca global do portfólio",
        qmTraceSearchRequirement: "Busca global",
        qmTraceSearchStory: "Busca",
        qmTraceSearchBDD: "Busca global",
        qmTraceSearchStatus: "Implementado e verificado",
        qmTraceSearchVerification: "Busca global implementada e verificada por meio de testes funcionais e de regressão automatizados com Selenium. Permite realizar buscas por termos exatos, parciais e relacionados, consultar resultados das diferentes páginas do portfólio e navegar diretamente para as seções correspondentes. A suíte de busca global registra 43/43 testes aprovados no Chrome, 43/43 no Firefox e 43/43 no Edge, totalizando 129/129 execuções aprovadas.",

        qmDefectsTitle: "05. Gestão de Defeitos",
        qmDefectsDescription: "A gestão de defeitos envolve a identificação, documentação, comunicação, verificação e encerramento dos problemas detectados durante os testes. Esse processo permite manter evidências, facilitar a colaboração da equipe e verificar se as correções atendem aos resultados esperados.",
        qmDefectProcessEyebrow: "PROCEDIMENTO DE QA",
        qmDefectProcessTitle: "Da identificação à verificação",
        qmDefectProcessDescription: "Durante o desenvolvimento do portfólio, comecei a acompanhar os defeitos por meio de registros estruturados no Excel e, posteriormente, incorporei o Jira para organizar sua documentação, classificação e acompanhamento. Esse processo permite aplicar boas práticas de QA em ambientes de trabalho colaborativos e equipes Scrum.",
        qmDefectStepsAria: "Etapas da gestão de defeitos",
        qmDefectStep01Short: "Detectar",
        qmDefectStep01Subtitle: "Identificação e evidências",
        qmDefectStep02Short: "Registrar",
        qmDefectStep02Subtitle: "Relatório documental",
        qmDefectStep03Short: "Comunicar",
        qmDefectStep03Subtitle: "Reprodução e correção",
        qmDefectStep04Short: "Testar novamente",
        qmDefectStep04Subtitle: "Validação da solução",
        qmDefectStep05Short: "Encerrar",
        qmDefectStep05Subtitle: "Encerramento documental",
        qmDefectActivitiesTitle: "Informações e atividades principais",
        qmDefectPrevious: "← Anterior",
        qmDefectNext: "Próximo →",
        qmDefectRetestTitle: "Verificação antes do encerramento",
        qmDefectRetestDescription: "Se o defeito continuar sendo reproduzido durante o novo teste, ele não deve ser encerrado. Seu registro de acompanhamento é atualizado e retorna ao processo de análise e correção. O encerramento ocorre somente após a verificação satisfatória do comportamento esperado.",
        qmDefectEvidenceEyebrow: "EVIDÊNCIAS DO PROJETO",
        qmDefectEvidenceTitle: "Defeitos documentados",
        qmDefectEvidenceDescription: "Os seguintes defeitos foram identificados durante os testes do portfólio e possuem registros de acompanhamento. Selecione um identificador para consultar o problema, sua classificação e as verificações relacionadas.",
        qmBugSelectorAria: "Selecionar defeito documentado",
        qmBugRequirementLabel: "Requisito relacionado",
        qmBugTestLabel: "Caso de teste",
        qmBugSeverityLabel: "Severidade",
        qmBugPriorityLabel: "Prioridade",
        qmBugResolutionTitle: "Resolução e verificação",
        qmDefectDocumentationDescription: "Os relatórios completos de defeitos, os casos de teste e as evidências disponíveis encontram-se na seção de QA do portfólio.",
        qmDefectDocumentationLink: "Consultar testes de regressão e defeitos →",
        qmDefectFinalNote: "Os cinco defeitos constam como encerrados nos registros do projeto. As classificações, os casos de teste relacionados e as evidências de verificação são apresentados conforme a documentação disponível para cada ocorrência, sem atribuir execuções adicionais não registradas.",
        qmDefectStep01Title: "Detecção e evidências",
        qmDefectStep01Label: "Identificação do defeito",
        qmDefectStep01Description: "Durante a execução dos testes, identifica-se um comportamento que não corresponde ao resultado esperado. São registrados os dados de teste, o ambiente e as evidências disponíveis, como capturas de tela ou gravações, para demonstrar o problema e facilitar sua reprodução.",
        qmDefectStep01Activity01: "Identificar a funcionalidade afetada.",
        qmDefectStep01Activity02: "Comparar o resultado esperado com o resultado obtido.",
        qmDefectStep01Activity03: "Capturar telas ou gravações do comportamento.",
        qmDefectStep01Activity04: "Registrar o ambiente e os dados de teste utilizados.",
        qmDefectStep02Title: "Registro documental",
        qmDefectStep02Label: "Excel e Jira",
        qmDefectStep02Description: "Após a identificação do defeito, é criado um registro documental. Neste projeto, o acompanhamento começou com planilhas do Excel e, posteriormente, o Jira foi incorporado para organizar as informações, a classificação e o acompanhamento dos defeitos.",
        qmDefectStep02Activity01: "Atribuir um identificador e um resumo claro.",
        qmDefectStep02Activity02: "Documentar a descrição e as etapas de reprodução.",
        qmDefectStep02Activity03: "Registrar a severidade, a prioridade e o estado.",
        qmDefectStep02Activity04: "Relacionar requisitos, casos de teste e evidências.",
        qmDefectStep03Title: "Comunicação e correção",
        qmDefectStep03Label: "Trabalho colaborativo",
        qmDefectStep03Description: "Além de registrar o defeito, é necessário comunicá-lo à equipe para que possa ser analisado e reproduzido. O responsável técnico analisa o problema, implementa a correção e informa quando ela está disponível para uma nova verificação. No Jira, é possível acompanhar o responsável e o estado da ocorrência.",
        qmDefectStep03Activity01: "Comunicar o defeito e seu impacto.",
        qmDefectStep03Activity02: "Fornecer as etapas e os dados de reprodução.",
        qmDefectStep03Activity03: "Acompanhar o responsável e a correção.",
        qmDefectStep03Activity04: "Confirmar que existe uma versão disponível para um novo teste.",
        qmDefectStep04Title: "Novo teste e validação",
        qmDefectStep04Label: "Controle de qualidade",
        qmDefectStep04Description: "Após a aplicação da correção, a equipe de QA executa novamente o cenário que permitiu identificar o defeito. O resultado obtido é comparado com o resultado esperado e, quando necessário, são realizados testes de regressão para verificar se outras funcionalidades continuam funcionando corretamente.",
        qmDefectStep04Activity01: "Executar novamente o caso de teste afetado.",
        qmDefectStep04Activity02: "Comparar o resultado obtido com o esperado.",
        qmDefectStep04Activity03: "Preservar as evidências coletadas após a correção.",
        qmDefectStep04Activity04: "Verificar as funcionalidades relacionadas.",
        qmDefectStep05Title: "Encerramento documental",
        qmDefectStep05Label: "Defeito verificado",
        qmDefectStep05Description: "Quando a correção é aprovada no novo teste, o defeito pode ser marcado como encerrado. Seu histórico, as evidências e as referências aos testes realizados são preservados. Se o problema persistir, ele retorna ao processo de análise e correção em vez de ser encerrado.",
        qmDefectStep05Activity01: "Confirmar que o resultado esperado foi alcançado.",
